#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n == 2) {
        printf("-1\n");
        return 0;
    }

    if (n == 1) {
        printf("1\n");
        return 0;
    }

    long long v[45];
    if (n % 2 != 0) {
        for (int i = 0; i < n; i++) {
            v[i] = i + 1;
        }
    } else {
        for (int i = 0; i < n - 1; i++) {
            v[i] = i + 1;
        }
        v[n - 1] = (long long)n * (n - 1) / 2;
    }

    long long max_val = v[n - 1];
    long long m = max_val + 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            long long val = v[j] + m * (v[i] - 1);
            printf("%lld%c", val, (j == n - 1) ? '\n' : ' ');
        }
    }

    return 0;
}
